// Функция для форматирования даты в YYYY-MM-DD
function formatDate(date) {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

// Функция для расчёта дедлайна (+3 дня)
function getDeadline() {
    const date = new Date();
    date.setDate(date.getDate() + 3);
    return formatDate(date);
}

// Функция для преобразования employment_type
function getEmploymentType(employment) {
    const employmentMap = {
        'full': 'fulltime',
        'part': 'parttime',
        'intern': 'intern',
        'стажировка': 'intern',
        'project': 'fulltime',
        'volunteer': 'intern'
    };
    const empLower = (employment || '').toLowerCase();
    return employmentMap[empLower] || 'fulltime';
}

// Функция для определения источника
function getSource(source) {
    if (source === 'hh.ru') return 'hh';
    if (source === 'Хабр Карьера') return 'habr';
    return source || 'unknown';
}

// Функция для формирования объяснения рейтинга
function getMatchReason(title, content, rating) {
    const reasons = [];
    const titleLower = (title || '').toLowerCase();
    const contentLower = (content || '').toLowerCase();

    const keywords = {
        'AI/нейросети': ['ии', 'нейросет', 'искусственный интеллект', 'gpt', 'ai'],
        'no-code/low-code': ['no-code', 'nocode', 'low-code', 'lowcode'],
        'автоматизация': ['автоматизац', 'оптимизац', 'эффективност', 'robotics'],
        'управление проектами': ['project', 'pm', 'agile', 'scrum', 'канбан', 'waterfall'],
        'позиция (стажёр/помощник)': ['стажер', 'помощник', 'младший', 'junior', 'trainee', 'ассистент']
    };

    for (const [category, words] of Object.entries(keywords)) {
        for (const word of words) {
            if (titleLower.includes(word)) {
                reasons.push(`${category} (+3 балла в названии)`);
                break;
            } else if (contentLower.includes(word)) {
                reasons.push(`${category} (+1 балл в описании)`);
                break;
            }
        }
    }

    if (reasons.length === 0) {
        return `Совпадений по ключевым словам не найдено. Рейтинг: ${rating}`;
    }

    return `Рейтинг: ${rating}\n\n✅ ${reasons.slice(0, 3).join('\n✅ ')}`;
}

